  ('hi', 'skills.invalid.header', $json$"SKILL.md की शुरुआत --- पंक्तियों के बीच के हेडर से होनी चाहिए।"$json$::jsonb),
  ('ar', 'skills.invalid.header', $json$"يجب أن يبدأ ملف SKILL.md بترويسة بين سطرين ---."$json$::jsonb),
  ('fr', 'skills.invalid.header', $json$"Le SKILL.md doit commencer par un en-tête entre deux lignes ---."$json$::jsonb),
